-- Data-structure single-choice import based on:
-- /Users/permer/Documents/408资料/2027数据结构_高清带书签版.pdf
-- Batch: DS-2027-001

INSERT INTO questions (
    id, subject_id, chapter_id, type, difficulty, stem, answer, explanation,
    source, source_year, score, status, review_status, review_note,
    stem_format, stem_image_url, reviewed_at, created_at, updated_at
)
SELECT
    CAST(q.id AS UUID),
    s.id,
    c.id,
    'SINGLE_CHOICE',
    q.difficulty,
    q.stem,
    q.answer,
    q.explanation,
    'MOCK',
    2027,
    2.00,
    'PUBLISHED',
    'APPROVED',
    '基于 /Users/permer/Documents/408资料/2027数据结构_高清带书签版.pdf 的教材章节与单选题考点改写导入。',
    'PLAIN_TEXT',
    NULL,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000021001','DS_LINEAR_LIST','BASIC','一个完整的数据结构通常包含哪三方面内容？','C','数据结构通常由逻辑结构、存储结构以及定义在结构上的数据运算三部分构成。'),
    ('00000000-0000-0000-0000-000000021002','DS_LINEAR_LIST','BASIC','下列结构中，属于非线性逻辑结构的是？','A','树结构中一个结点可以有多个后继，元素之间不是一对一关系，因此属于非线性结构。'),
    ('00000000-0000-0000-0000-000000021003','DS_LINEAR_LIST','MEDIUM','顺序存储结构最突出的优点是？','B','顺序存储用连续地址保存元素，能够根据下标直接计算地址，实现随机存取。'),
    ('00000000-0000-0000-0000-000000021004','DS_LINEAR_LIST','MEDIUM','链式存储结构相对顺序存储的主要特点是？','D','链式存储不要求逻辑相邻元素物理相邻，通过指针维护元素关系，插入删除较灵活。'),
    ('00000000-0000-0000-0000-000000021005','DS_LINEAR_LIST','BASIC','算法的有穷性指的是？','A','有穷性要求算法必须在执行有限步之后结束，而不是无限执行。'),
    ('00000000-0000-0000-0000-000000021006','DS_LINEAR_LIST','MEDIUM','若某算法只使用与问题规模无关的固定辅助变量，则其空间复杂度通常为？','B','只使用固定数量的辅助空间时，额外空间不随 n 增长，空间复杂度为 O(1)。'),
    ('00000000-0000-0000-0000-000000021007','DS_LINEAR_LIST','MEDIUM','在长度为 n 的顺序表中删除第 i 个元素，需要移动的元素个数是？','C','删除第 i 个元素后，第 i+1 到第 n 个元素都要前移，因此移动 n - i 个元素。'),
    ('00000000-0000-0000-0000-000000021008','DS_LINEAR_LIST','HARD','顺序表按值查找第一个等于 e 的元素，在等概率成功查找时平均比较次数约为？','D','目标元素等概率位于 1 到 n 位时，平均比较次数为 (1+2+...+n)/n = (n+1)/2。'),
    ('00000000-0000-0000-0000-000000021009','DS_LINEAR_LIST','BASIC','静态链表中的“指针”本质上通常保存什么？','A','静态链表用数组模拟链表，next 域保存的是下一个结点在数组中的下标，也称游标。'),
    ('00000000-0000-0000-0000-000000021010','DS_LINEAR_LIST','MEDIUM','循环双链表为空时，头结点的 prior 和 next 通常满足什么关系？','B','空循环双链表中头结点的 prior 和 next 都指向自身。'),
    ('00000000-0000-0000-0000-000000021011','DS_STACK_QUEUE','BASIC','顺序栈入栈操作在数组实现中通常伴随哪一动作？','C','顺序栈常用 top 指示栈顶，入栈时先移动 top 再写入或先写入再移动，核心是修改栈顶位置。'),
    ('00000000-0000-0000-0000-000000021012','DS_STACK_QUEUE','MEDIUM','判断一个给定序列是否为合法出栈序列，常用的基本方法是？','D','可按入栈序列模拟入栈和出栈过程，若能按目标序列依次弹出，则该出栈序列合法。'),
    ('00000000-0000-0000-0000-000000021013','DS_TREE','BASIC','二叉树的第 k 层最多有多少个结点？根为第 1 层。','A','二叉树第 k 层最多有 2^(k-1) 个结点。'),
    ('00000000-0000-0000-0000-000000021014','DS_TREE','MEDIUM','树的双亲表示法中，每个结点通常额外保存什么信息？','B','双亲表示法在结点中保存其双亲结点在数组中的下标。'),
    ('00000000-0000-0000-0000-000000021015','DS_TREE','HARD','判断顺序存储二叉树是否为二叉搜索树时，核心依据是？','C','二叉搜索树要求任一结点大于其左子树所有结点并小于其右子树所有结点。'),
    ('00000000-0000-0000-0000-000000021016','DS_TREE','HARD','红黑树插入调整中，若父结点和叔结点均为红色，常见处理是？','D','父结点和叔结点均红时，通常将父和叔染黑、祖父染红，再继续向上检查。'),
    ('00000000-0000-0000-0000-000000021017','DS_GRAPH','BASIC','邻接矩阵存储无向图时，矩阵通常具有哪种性质？','A','无向图边 (i,j) 与 (j,i) 同时存在，因此邻接矩阵关于主对角线对称。'),
    ('00000000-0000-0000-0000-000000021018','DS_GRAPH','MEDIUM','Kruskal 算法构造最小生成树时，每次优先选择什么边？','B','Kruskal 算法按边权从小到大考察边，若加入后不形成回路则加入生成树。'),
    ('00000000-0000-0000-0000-000000021019','DS_GRAPH','MEDIUM','Kruskal 算法通常更适合哪类图？','C','Kruskal 的复杂度主要与边数和边排序有关，常用于边较少的稀疏图。'),
    ('00000000-0000-0000-0000-000000021020','DS_GRAPH','HARD','带权图中从单源到其他顶点的最短路径，若边权均非负，通常使用哪种算法？','D','Dijkstra 算法适用于边权非负的单源最短路径问题。'),
    ('00000000-0000-0000-0000-000000021021','DS_SORT','BASIC','直接插入排序在序列基本有序时，时间复杂度可接近？','A','序列基本有序时，直接插入排序比较和移动次数较少，可接近 O(n)。'),
    ('00000000-0000-0000-0000-000000021022','DS_SORT','MEDIUM','Shell 排序本质上是对哪种排序的改进？','B','Shell 排序通过分组增量预排序改进直接插入排序。'),
    ('00000000-0000-0000-0000-000000021023','DS_SORT','MEDIUM','堆排序中，每一趟将堆顶元素与当前无序区最后一个元素交换后，需要执行什么操作？','C','交换后堆结构可能被破坏，需要对剩余无序区重新调整为堆。'),
    ('00000000-0000-0000-0000-000000021024','DS_SORT','HARD','若排序算法每一趟都能确定至少一个元素的最终位置，下列算法通常符合这一特征的是？','D','冒泡、简单选择、堆排序和快速排序的每趟处理通常能确定至少一个元素的最终位置。')
) AS q(id, chapter_code, difficulty, stem, answer, explanation)
JOIN subjects s ON s.code = 'DATA_STRUCTURE'
JOIN chapters c ON c.code = q.chapter_code;

