INSERT INTO question_tags (id, name, created_at)
SELECT CAST(tag.id AS UUID), tag.name, CURRENT_TIMESTAMP
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000021701','2027数据结构'),
    ('00000000-0000-0000-0000-000000021702','DS-2027-001')
) AS tag(id, name)
WHERE NOT EXISTS (SELECT 1 FROM question_tags existing WHERE existing.name = tag.name);

INSERT INTO question_tag_relations (question_id, tag_id)
SELECT CAST(q.id AS UUID), tag.id
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000021001'),('00000000-0000-0000-0000-000000021002'),('00000000-0000-0000-0000-000000021003'),('00000000-0000-0000-0000-000000021004'),('00000000-0000-0000-0000-000000021005'),('00000000-0000-0000-0000-000000021006'),('00000000-0000-0000-0000-000000021007'),('00000000-0000-0000-0000-000000021008'),('00000000-0000-0000-0000-000000021009'),('00000000-0000-0000-0000-000000021010'),('00000000-0000-0000-0000-000000021011'),('00000000-0000-0000-0000-000000021012'),('00000000-0000-0000-0000-000000021013'),('00000000-0000-0000-0000-000000021014'),('00000000-0000-0000-0000-000000021015'),('00000000-0000-0000-0000-000000021016'),('00000000-0000-0000-0000-000000021017'),('00000000-0000-0000-0000-000000021018'),('00000000-0000-0000-0000-000000021019'),('00000000-0000-0000-0000-000000021020'),('00000000-0000-0000-0000-000000021021'),('00000000-0000-0000-0000-000000021022'),('00000000-0000-0000-0000-000000021023'),('00000000-0000-0000-0000-000000021024')
) AS q(id)
JOIN question_tags tag ON tag.name IN ('2027数据结构', 'DS-2027-001', '资料文档改写', '选择题扩容')
